#!/usr/bin/env python3
"""Assemble summary.md from tables.md (generated by scan.py) plus hand-written
sections. Every example snippet is checked to be a substring of the cited source
line; the script aborts if not.
Usage: python3 build_summary.py /path/to/instance
"""
import csv, os, sys
root = os.path.abspath(sys.argv[1]); here = os.path.dirname(os.path.abspath(__file__))
S = 'src/'
# construct -> [(path, line, snippet, postgres equivalent)]
