ZERO = ['json_arrow', 'limit_offset_comma', 'date_add', 'unix_timestamp', 'concat_ws', 'find_in_set', 'regexp', 'match_against', 'last_insert_id', 'lock_in_share', 'straight_join', 'index_hint', 'cast_char_binary', 'substring_index', 'insert_set', 'table_maint', 'sql_calc_found_rows', 'date_part_fns', 'cast_datetime', 'div_mod_kw']

rows = list(csv.DictReader(open(os.path.join(here, 'raw-sql.csv'))))
def tot(c): return sum(int(r[c]) for r in rows)
for c in ZERO:
    assert tot(c) == 0, (c, tot(c))
# verify examples
cache = {}
for c, items in EX.items():
    assert tot(c) > 0, c
    for p, ln, snip, pg in items:
        lines = cache.setdefault(p, open(os.path.join(root, p), encoding='utf-8').read().split('\n'))
        assert snip in lines[ln-1], 'example mismatch %s %s:%d' % (c, p, ln)

# query builder vs raw
qb = sum(1 for r in rows if int(r['qb_calls']) and not int(r['raw_sql_literals']))
raw = sum(1 for r in rows if int(r['raw_sql_literals']) and not int(r['qb_calls']))
both = sum(1 for r in rows if int(r['raw_sql_literals']) and int(r['qb_calls']))
neither = sum(1 for r in rows if not int(r['raw_sql_literals']) and not int(r['qb_calls']))
tables = open(os.path.join(here, 'tables.md')).read()

OUT = []
OUT.append('# Raw SQL outside the DAL: MySQL-specific construct inventory\n')
OUT.append('Generated with:\n\n```\npython3 -I scan.py <instance>      # writes raw-sql.csv, hits.tsv, tables.md, meta.json\npython3 -I build_summary.py <instance>   # writes this file, verifies every example line\n```\n')
OUT.append('where `<instance>` = `<repo>/instance`, run from `docs/inventory/raw-sql/`. All numbers below come from these two scripts.\n')
OUT.append('Scope rule (see `scan.py`): every `*.php` under `instance/src`, excluding any path containing `/Migration/` and `src/Core/Framework/DataAbstractionLayer/`; in scope if the file imports `Doctrine\\DBAL\\Connection` (`imports_connection`) or, without that import, calls an execute/fetch method, createQueryBuilder, MultiInsertQueryQueue or RetryableQuery/Transaction (`executes_sql_no_connection_import`). SQL constructs are matched only inside PHP string literals (comments and code are stripped first); PHP-side constructs only in code. Case-insensitive except where noted in (f). Test helpers that live under `src/` (for example `src/Core/Test`, `src/Elasticsearch/Test`) are included because they are under `src`.\n')
OUT.append('Raw SQL vs QueryBuilder, per file: raw-SQL literal only %d, QueryBuilder only %d, both %d, neither (only execute/fetch calls with SQL held elsewhere, or helper classes) %d.\n' % (raw, qb, both, neither))
OUT.append('Totals note: `sql_constructs_total` sums all SQL-string constructs except `lower_hex` (a subset of `hex_fn`). `json_fn` counts every JSON_* call once; the per-function split is in its own table. The PHP-side binary-uuid helpers (`uuid_*`, `array_param_binary`) are reported separately in `raw-sql.csv` (`sql_plus_php_binary_total`) and are not part of the Top 30 ranking.\n')
OUT.append(tables)

OUT.append('\n### (d) Examples per construct (verified: each snippet was checked as a substring of the cited line)\n')
for c, items in EX.items():
    OUT.append('**%s** (%d files, %d occurrences)\n' % (c, sum(1 for r in rows if int(r[c])), tot(c)))
    for p, ln, snip, pg in items:
        OUT.append('- `%s:%d`: `%s`\n  - PostgreSQL: %s' % (p, ln, snip, pg))
    OUT.append('')
OUT.append('**Constructs with zero hits in scope** (the script found none; for the first eleven of them a plain-text grep over the same in-scope files, run without the string/comment filter, found no SQL either, only prose such as "against" in comments and a config key named `regexp`; the rest were checked by the script only): ' + ', '.join('`%s`' % c for c in ZERO) + '.\n')
OUT.append(open(os.path.join(here, 'summary-tail.md')).read())
open(os.path.join(here, 'summary.md'), 'w').write('\n'.join(OUT))
print('ok examples verified:', sum(len(v) for v in EX.values()))
